Object.assign(TX.en,{pTitle:"Study plan",pNone:"Pick the level you are studying. The app works out how much to study each day and what to focus on.",pMore:"Details",pToday:"Today",pKana:"Write all Hiragana + Katakana",pDue:"Review due cards",pLeft:"{n} left",pNew:"New cards (words + Kanji)",pWrite:"Writing",pGram:"Grammar (Quiz)",pCloze:"Fill in",pRead:"Reading / Listening",pOn:"On track",pBehind:"{n} items behind plan",pEnd:"Expected finish:",pPick:"Target level:",pPace:"Pace (time for the whole level):",pPl:"Light",pPm:"Medium",pPf:"Fast",pMo:"months",pLearned:"Words/Kanji count as learned once studied as cards; grammar patterns after 2 correct quiz answers.",pDaily:"Every day",pDw:"{v} new words + {k} new Kanji (new cards per day is set to match)",pDg:"1 new grammar pattern every {n} days: read it in the Grammar tab, then Quiz → Grammar",pDgR:"Grammar for this level done, just review in the Quiz",pDwr:"Write {n} characters/words (Kanji you studied)",pDc:"{n} fill-in sentences",pDr:"{n} reading/listening questions",pTime:"About {n} minutes a day.",pOrder:"Order of a study session",pSteps:"Review due cards first (most important, don't let them pile up)|Today's new cards|Write the Kanji you just learned|Read 1 grammar pattern, then Quiz → Grammar|Fill-in and Reading/Listening to use words in sentences|Busy day? Just do steps 1 and 2",pFocus:"Focus for",pRestart:"Recalculate from today",pOff:"Turn plan off",pAuto:"Following your study plan: recalculated daily. Turn the plan off to choose yourself.",plan:"Plan"});
/* ---------- Forgotten list ("Đã quên") ----------
   S.fg[id]=[active lapses (>0 = in the list), updated, step 0-3, source, readyAt, total lapses]
   IN : "Again" on a card you had already learned, a wrong quiz answer (vocab / fill-in / verbs / listening),
        a failed Kanji recall in Writing, or the manual 🧠 button on a card.
   OUT: 3 correct recalls, spaced out: right away → after ≥1 hour → after ≥1 day. A wrong answer resets to step 0.
        Correct answers in Cards and in the Quiz both count, but only when the word is "ready" (wait time passed). */
const FGI=[0,36e5,DAY],FGN=3,FGS={c:"🗂",q:"✏️",z:"🧩",v:"🔁",l:"🎧",w:"✍️",m:"👆"};
function fgOn(x){const e=S.fg[x.id];return!!(e&&e[0]>0)}
const fgReady=x=>fgOn(x)&&(S.fg[x.id][4]||0)<=Date.now(),fgStep=x=>(S.fg[x.id]||[])[2]||0;
const fgDots=x=>"●".repeat(fgStep(x))+"○".repeat(FGN-fgStep(x));
const fgN=()=>[...D.vocab,...D.kanji].filter(fgOn).length,fgR=()=>[...D.vocab,...D.kanji].filter(fgReady).length;
function toast(m){let e=$("#toast");if(!e){e=document.createElement("div");e.id="toast";document.body.appendChild(e)}e.textContent=m;e.className="on";clearTimeout(toast.t);toast.t=setTimeout(()=>e.className="",2600)}
function addFg(x,src){const e=S.fg[x.id]||[],was=fgOn(x);S.fg[x.id]=[(was?e[0]:0)+1,Date.now(),0,src||e[3]||"",0,(e[5]||e[0]||0)+1];save();toast("🧠 "+x.j+" — "+t(was?"fgAgain":"fgAdd"))}
function fgUpd(x,g){if(g==0)return addFg(x,"c");if(!fgReady(x))return;const e=S.fg[x.id],s=(e[2]||0)+1,tot=e[5]||e[0];
if(s>=FGN){S.fg[x.id]=[0,Date.now(),FGN,e[3],0,tot];toast("🎉 "+x.j+" — "+t("fgPass"))}else{S.fg[x.id]=[e[0],Date.now(),s,e[3],Date.now()+FGI[s],tot];toast("✓ "+x.j+" "+fgDots(x)+" — "+t("fgNext").replace("{t}",fmt(FGI[s])))}save()}
function fgOff(id){const e=S.fg[id];if(e)S.fg[id]=[0,Date.now(),FGN,e[3],0,e[5]||e[0]];save();render()}
function fgToggle(){const x=cur;if(fgOn(x))fgOff(x.id);else{addFg(x,"m");render()}}
let fgList=false;
const fgInfo=x=>{const e=S.fg[x.id],w=(e[4]||0)-Date.now();return`${fgDots(x)} · ${FGS[e[3]]||""} ${t("fgTimes").replace("{n}",e[0])} · ${w>0?"⏳ "+fmt(w):"✅ "+t("fgRdy")}`};
function FgHead(){const all=[...D.vocab,...D.kanji].filter(x=>fgOn(x)&&inF(x)),rd=all.filter(fgReady),wt=all.filter(x=>!fgReady(x)),nx=wt.length?Math.min(...wt.map(x=>S.fg[x.id][4]))-Date.now():0,
ps=[...D.vocab,...D.kanji].filter(x=>{const e=S.fg[x.id];return e&&!e[0]&&e[2]==FGN&&Date.now()-e[1]<7*DAY}).length;
return`<div class="card fgh"><div class="fgs"><div><b>${rd.length}</b><span class="mu">${t("fgRdy")}</span></div><div><b>${wt.length}</b><span class="mu">${t("fgWait")}${wt.length?" · "+fmt(nx):""}</span></div><div><b>${ps}</b><span class="mu">${t("fgPs7")}</span></div></div>
<details><summary class="mu">ℹ️ ${t("fgHow")}</summary><ul class="pl"><li>${t("fgIn")}</li><li>${t("fgOut")}</li><li>${t("fgCnt")}</li></ul></details>
<button class="pill" style="margin-top:6px" onclick="fgList=!fgList;render()">📋 ${t("fgLst")} (${all.length}) ${fgList?"▲":"▼"}</button>
${fgList?`<div class="fgl">${all.sort((a,b)=>(S.fg[a.id][4]||0)-(S.fg[b.id][4]||0)).map(x=>`<div class="fgi"><div><b>${x.j}</b> <span class="mu">${x.r}</span><br><span class="mu" style="font-size:12.5px">${x[S.lang]}</span></div><div class="mu" style="font-size:12.5px;text-align:right">${fgInfo(x)}<br><button class="pill" onclick="fgOff('${x.id}')">✓ ${t("fgRm")}</button></div></div>`).join("")||`<p class="mu">${t("noFg")}</p>`}</div>`:""}</div>`}
Object.assign(TX.vi,{fgAdd:"đã thêm vào 🧠 Đã quên",fgAgain:"quên lại, tiến độ về 0",fgPass:"đã thuộc lại, ra khỏi 🧠 Đã quên",fgNext:"lần tiếp sau {t}",fgTimes:"quên {n} lần",fgRdy:"sẵn sàng",fgWait:"đang chờ",fgPs7:"thuộc lại (7 ngày)",fgHow:"Cách hoạt động",fgIn:"Từ VÀO danh sách khi: chọn \"Quên\" ở thẻ đã học, trả lời sai ở Kiểm tra (Từ vựng, Điền từ, Chia động từ, Nghe), viết Kanji không đạt (chế độ Không hướng dẫn), hoặc bấm 🧠 trên thẻ. App sẽ báo ngay khi có từ mới vào.",fgOut:"Từ RA khỏi danh sách khi nhớ đúng 3 lần ●●●: lần 1 ngay, lần 2 sau ít nhất 1 giờ, lần 3 sau ít nhất 1 ngày. Sai thì quay về ○○○.",fgCnt:"Trả lời đúng ở thẻ (Nhớ/Dễ) hoặc ở Kiểm tra đều được tính, nhưng chỉ khi từ đã \"sẵn sàng\" (hết thời gian chờ). Muốn bỏ ngay thì bấm ✓ Bỏ trong danh sách.",fgLst:"Danh sách",fgRm:"Bỏ",fgWaitAll:"Các từ đã quên đều đang chờ. Lần ôn tiếp sau",fgMark:"Đánh dấu đã quên",fgCard:"Đã quên"});
Object.assign(TX.en,{fgAdd:"added to 🧠 Forgotten",fgAgain:"forgotten again, progress reset",fgPass:"remembered, removed from 🧠 Forgotten",fgNext:"next check in {t}",fgTimes:"forgotten {n}×",fgRdy:"ready",fgWait:"waiting",fgPs7:"recovered (7 days)",fgHow:"How it works",fgIn:"Words go IN when you press \"Again\" on a card you had learned, answer wrong in the Quiz (Vocab, Fill-in, Verbs, Listening), fail a Kanji in Writing (recall mode), or tap 🧠 on a card. You get a notice each time.",fgOut:"Words come OUT after 3 correct recalls ●●●: first right away, second after at least 1 hour, third after at least 1 day. A wrong answer resets to ○○○.",fgCnt:"Correct answers in Cards (Good/Easy) and in the Quiz both count, but only when the word is \"ready\" (wait time over). To drop a word now, tap ✓ Drop in the list.",fgLst:"List",fgRm:"Drop",fgWaitAll:"All forgotten words are waiting. Next review in",fgMark:"Mark as forgotten",fgCard:"Forgotten"});
/* ---------- Vocab quiz: 4 question types per word ----------
   m = word → meaning, w = meaning → word, r = word → reading (Kanji words), l = listen → meaning. S.qt: "x" = mixed */
const QT=["m","w","r","l"];
function newQ(){const d=D.vocab.filter(inF),p=d.length>=4?d:D.vocab;Q=null;if(!p.length)return;const pk=S.qt=="r"?p.filter(y=>/[一-龥]/.test(y.j)):p;if(!pk.length)return;const x=pk[Math.random()*pk.length|0];
let k=S.qt&&S.qt!="x"?S.qt:QT[Math.random()*4|0];if(k=="r"&&!/[一-龥]/.test(x.j))k="m";
const key=k=="r"?y=>y.r:k=="w"?y=>y.j:y=>y[S.lang],o=[x],iv=/^to /.test(x.en);let pool;
if(k=="r"){const sh=D.vocab.filter(y=>y!==x&&[...x.j].some(c=>/[一-龥]/.test(c)&&y.j.includes(c)));pool=[...shuf(sh).slice(0,2),...shuf(D.vocab.filter(y=>/[一-龥]/.test(y.j)&&Math.abs(y.r.length-x.r.length)<=1&&Math.abs(y.l-x.l)<=1))]}
else{const nr=D.vocab.filter(y=>Math.abs(y.l-x.l)<=1&&/^to /.test(y.en)==iv);pool=shuf(nr.length>=12?nr:D.vocab.slice())}
for(const y of pool){if(o.length>=4)break;if(!o.some(z=>z===y||key(z)===key(y)||(k!="r"&&z[S.lang]===y[S.lang])))o.push(y)}
if(o.length<4)return;Q={x,k,o:shuf(o),a:-1};if(k=="l")setTimeout(()=>speak(x.r),350)}
function ans(i){if(Q.a>=0)return;Q.a=i;sc[1]++;if(Q.o[i]===Q.x){sc[0]++;tick(5);fgUpd(Q.x,1)}else{tick(1);addFg(Q.x,"q")}speak(Q.x.r);render()}
function WQuiz(){if(!Q)newQ();const tp=`<div class="row">${["x",...QT].map(k=>`<button class="pill ${(S.qt||"x")==k?"on":""}" onclick="S.qt='${k}';Q=null;save();render()">${t("qt"+k.toUpperCase())}</button>`).join("")}</div>`;
if(!Q)return chips()+tp+`<p class="c mu">${t("none")}</p>`;const{x,k,a}=Q,done=a>=0,n=D.vocab.filter(inF).length;
const top=k=="w"?`<div class="big" style="font-size:30px;line-height:1.3">${x[S.lang]}</div>`:k=="l"?`<button class="go" style="font-size:22px;padding:18px 28px;margin:10px auto;display:block" onclick="speak(Q.x.r)">🔊 ${t("qtLp")}</button>${done?`<div class="big">${x.j}</div>`:""}`:`<div class="big">${x.j}</div>`;
const sub=done?`<div class="c mu">${x.r} · ${x[S.lang]}</div>`:"",lab=y=>k=="r"?y.r:k=="w"?y.j+(done?` <span class="mu">(${y.r})</span>`:""):y[S.lang];
return chips()+tp+`<div class="card"><div class="mu">${t("qtQ"+k.toUpperCase())} · ${t("score")} ${sc[0]}/${sc[1]}</div>${k!="l"?`<button class="pill" onclick="speak(Q.x.r)">🔊 ${t("listen")}</button>`:""}${top}${sub}${Q.o.map((o,i)=>`<button class="opt ${done?(o===x?"ok":i===a?"bad":""):""}" onclick="ans(${i})">${lab(o)}</button>`).join("")}${done&&fgOn(x)?`<p class="mu c" style="font-size:12.5px">🧠 ${fgInfo(x)}</p>`:""}</div>${done?`<button class="go" style="width:100%" onclick="newQ();render()">${t("next")} →</button>`:""}<p class="mu c" style="font-size:12.5px">${t("qtInfo").replace("{n}",n).replace("{q}",n*4)}</p>`}
Object.assign(TX.vi,{qtX:"🔀 Trộn",qtM:"Từ → Nghĩa",qtW:"Nghĩa → Từ",qtR:"Cách đọc",qtL:"🎧 Nghe",qtQM:"Chọn nghĩa đúng",qtQW:"Chọn từ tiếng Nhật đúng",qtQR:"Chọn cách đọc đúng",qtQL:"Nghe rồi chọn nghĩa",qtLp:"Nghe",qtInfo:"{n} từ × 4 dạng câu hỏi (nghĩa, từ, cách đọc, nghe) ≈ {q} câu. Mỗi lần ra ngẫu nhiên.",czInfo:"{w} từ · {s} câu hỏi điền từ (mỗi từ lần lượt dùng hết các câu của nó rồi mới lặp lại)."});
Object.assign(TX.en,{qtX:"🔀 Mixed",qtM:"Word → Meaning",qtW:"Meaning → Word",qtR:"Reading",qtL:"🎧 Listen",qtQM:"Choose the meaning",qtQW:"Choose the Japanese word",qtQR:"Choose the reading",qtQL:"Listen and choose the meaning",qtLp:"Play",qtInfo:"{n} words × 4 question types (meaning, word, reading, listening) ≈ {q} questions, picked at random.",czInfo:"{w} words · {s} fill-in questions (each word cycles through all its sentences before repeating)."});
function Home(){newDay();const q=[D.vocab,D.kanji].map(a=>queue(a.filter(inF))),du=q[0].due.length+q[1].due.length,nn=Math.min(q[0].nw.length+q[1].nw.length,Math.max(0,S.nl+S.xt-S.nn)),g=Math.min(S.td,10);
return`<div class="card st"><div><b>🔥${S.st}</b><span class="mu">${t("streak")}</span></div><div><b>⭐${S.xp}</b><span class="mu">${t("xp")}</span></div><div><b>${S.td}</b><span class="mu">${t("today")}</span></div></div>
<div class="card"><b>${t("due")}: ${du}</b> · ${t("nw")}: ${nn}<div class="bar" style="margin:10px 0"><i style="width:${g*10}%"></i></div><button class="go" style="width:100%" onclick="go('cards')">🗂 ${t("startR")}</button></div>
${PlanCard()}${chips()}<div class="card"><b>${t("prog")}</b>${[5,4,3].map(l=>{const a=[...D.vocab,...D.kanji].filter(x=>x.l==l),m=a.filter(x=>S.b[x.id]&&S.b[x.id][0]>=3).length;return`<div class="mu" style="margin-top:10px">N${l} · ${m}/${a.length} ${t("mast")}</div><div class="bar"><i style="width:${a.length?m/a.length*100:0}%"></i></div>`}).join("")}</div>${fgN()?`<div class="card"><b>🧠 ${t("fgHome")}: ${fgN()}</b> <span class="mu">· ${t("fgRdy")}: ${fgR()}</span><button class="no" style="width:100%;margin-top:10px" onclick="S.mode='f';cur=null;go('cards')">${t("startR")}</button></div>`:""}${Hist()}${bkWarn()}<div class="two"><button class="no" onclick="go('quiz')">✏️ ${t("quiz")}</button><button onclick="go('set')">⚙️ ${t("set")}</button></div>`}
function Hist(){const ds=[...Array(14)].map((_,i)=>{const d=new Date(Date.now()-(13-i)*DAY);return[dkey(d),d]}),mx=Math.max(10,...ds.map(d=>(S.h[d[0]]||[0])[0])),v=Object.values(S.h),tot=v.reduce((a,e)=>[a[0]+e[0],a[1]+e[1]],[0,0]);if(!v.length)return"";
return`<div class="card"><b>📈 ${t("hist")}</b><div class="hc">${ds.map(([k,d])=>{const e=S.h[k]||[0,0,0];return`<div title="${k}: ${e[0]} · ${e[1]}✓"><i style="height:${Math.round(e[0]/mx*100)}%"></i><span>${d.getDate()}</span></div>`}).join("")}</div><div class="mu">${t("hDays")}: ${v.length} · ${t("hAns")}: ${tot[0]} · ${t("hAcc")}: ${tot[0]?Math.round(tot[1]/tot[0]*100):0}%</div></div>`}
const bkWarn=()=>{if(S.sb.code||Object.keys(S.b).length<20||Date.now()-S.lb<7*DAY)return"";return`<div class="card"><b>💾 ${t("bkR")}</b><p class="mu">${S.lb?t("bkD")+": "+new Date(S.lb).toLocaleDateString():t("bkN")}. ${t("bkH")}</p><button class="go" style="width:100%" onclick="bk()">💾 ${t("bk")}</button></div>`};
function Cards(){if(!cur)cur=pick();const m=`<div class="row"><button class="pill ${S.mode=="v"?"on":""}" onclick="S.mode='v';cur=null;render()">${t("voc")}</button><button class="pill ${S.mode=="k"?"on":""}" onclick="S.mode='k';cur=null;render()">${t("kan")}</button><button class="pill ${S.mode=="f"?"on":""}" onclick="S.mode='f';cur=null;render()">🧠 ${t("fg")} (${fgR()}/${fgN()})</button>${S.mode!="f"?`<button class="pill ${S.rp?"on":""}" onclick="S.rp=!S.rp;cur=null;recent=[];save();render()">🔀 ${t("rp")}</button>`:""}</div>${S.rp&&S.mode!="f"?`<p class="mu" style="font-size:12.5px;margin:2px 0">${t("rpH")}</p>`:""}`;
const fh=S.mode=="f"?FgHead():"";
if(!cur){const d=deck(),q=queue(d),nx=d.filter(x=>S.b[x.id]&&S.b[x.id][1]>Date.now()).map(x=>S.b[x.id][1]);const fw=S.mode=="f"?[...D.vocab,...D.kanji].filter(x=>fgOn(x)&&inF(x)).map(x=>S.fg[x.id][4]||0):[];
return m+chips()+fh+`<div class="card c"><div class="big">${fw.length?"⏳":"🎉"}</div><p>${d.length?t("done"):S.mode=="f"?(fw.length?t("fgWaitAll")+" "+fmt(Math.min(...fw)-Date.now()):t("noFg")):t("none")}</p>${nx.length?`<p class="mu">${t("nextIn")} ${fmt(Math.min(...nx)-Date.now())}</p>`:""}<div class="row" style="justify-content:center">${q.nw.length?`<button class="go" onclick="S.xt+=10;cur=null;render()">${t("more")}</button>`:""}${d.length&&S.mode!="f"?`<button onclick="S.rp=true;cur=null;save();render()">🔀 ${t("rpGo")}</button>`:""}</div></div>`}
const c=cur,e=S.b[c.id],b=e?e[0]:0,sc2=sched(c),lb2=k=>sc2?`<br><small>${lbl(k)}</small>`:"";
return m+chips()+fh+`<div class="card fc" onclick="flip=!flip;if(flip)speak(cur.r.split('・')[0]);render()"><div class="big">${c.j}</div>${flip?`<div style="font-size:20px">${c.r}</div><div style="margin-top:8px">🇬🇧 ${c.en}</div><div>🇻🇳 ${c.vi}</div>${c.id[0]=="v"?exs(c):kvs(c)}`:`<div class="mu" style="margin-top:12px">${t("flip")}</div>`}<button class="pill" style="margin-top:10px" onclick="event.stopPropagation();speak(cur.r.split('・')[0])">🔊</button><div class="mu" style="margin-top:10px">N${c.l} · ${thLabel(c)} · ${"●".repeat(b)}${"○".repeat(5-b)}</div>${fgOn(c)?`<div class="fgc">🧠 ${t("fgCard")}: ${fgInfo(c)}</div>`:""}${flip&&S.b[c.id]?`<button class="pill" style="margin-top:8px" onclick="event.stopPropagation();fgToggle()">${fgOn(c)?"✓ "+t("fgRm"):"🧠 "+t("fgMark")}</button>`:""}</div>
${flip?`<div class="two3"><button class="no" onclick="rate(0)">${t("again")}<br><small>${lbl(0)}</small></button><button class="go" onclick="rate(1)">${t("good")}${lb2(Math.min(b+1,5))}</button><button onclick="rate(2)">${t("easy")}${lb2(Math.min(b+2,5))}</button></div>`:""}`}
/* ---------- Quiz: vocab + conjugation ---------- */
let VQ=null,vsc=[0,0];
function newVQ(){const vs=D.vocab.filter(x=>inL(x)&&isV(x));if(!vs.length){VQ=null;return}const F=["ます","て","ない","た"],x=vs[Math.random()*vs.length|0],f=S.vf&&S.vf!="all"?S.vf:F[Math.random()*4|0],g=grp(x),c=fm(cj(x,f)),w=new Set(F.filter(y=>y!=f).map(y=>fm(cj(x,y))));if(g!=3)w.add(fm(cj(x,f,g==2?1:2)));w.delete(c);VQ={x,f,g,c,o:[c,...[...w].sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5),a:-1}}
function vans(i){if(VQ.a>=0)return;VQ.a=i;vsc[1]++;if(VQ.o[i]==VQ.c){vsc[0]++;tick(5);fgUpd(VQ.x,1)}else{tick(1);addFg(VQ.x,"v")}speak(cj(VQ.x,VQ.f)[1]);render()}
function VQuiz(){if(!VQ)newVQ();const fc=`<div class="row">${["all","ます","て","ない","た"].map(f=>`<button class="pill ${(S.vf||"all")==f?"on":""}" onclick="S.vf='${f}';VQ=null;save();render()">${f=="all"?t("allF"):FL[f]}</button>`).join("")}</div>`;if(!VQ)return chips()+fc+`<p class="c mu">${t("none")}</p>`;
const{x,f,g,o,c,a}=VQ;return chips()+fc+`<div class="card"><div class="mu">${t("q")} · ${t("score")} ${vsc[0]}/${vsc[1]}</div><div class="big" style="font-size:48px" onclick="speak('${x.r}')">${x.j}</div><div class="c mu">${x.r} · ${x[S.lang]}</div><div class="c" style="margin:10px 0"><b>→ ${FL[f]}</b></div>${o.map((s,i)=>`<button class="opt ${a>=0?(s==c?"ok":i==a?"bad":""):""}" onclick="vans(${i})">${s}</button>`).join("")}${a>=0?`<div class="mu" style="margin-top:10px">${t("grp")} ${g}<br>${["ます","て","ない","た"].map(y=>FL[y]+": "+fm(cj(x,y))).join("<br>")}</div>`:""}</div>${a>=0?`<button class="go" style="width:100%" onclick="newVQ();render()">${t("next")} →</button>`:""}`}
function Quiz(){return`<div class="row">${[["w",t("voc")],["v",t("verbs")],["c",t("cloze")],["g",t("gram")]].map(a=>`<button class="pill ${S.qm==a[0]?"on":""}" onclick="S.qm='${a[0]}';save();render()">${a[1]}</button>`).join("")}</div><p class="mu kb">⌨️ ${t("kKb")}</p>`+(S.qm=="v"?VQuiz():S.qm=="c"?CQuiz():S.qm=="g"?GQuiz():WQuiz())}
let gOpen=-1,gSearch="",GA=[];const gp=x=>plain(x).replace(/[{}]/g,""),hl=x=>ruby(x).replace(/\{/g,"<mark>").replace(/\}/g,"</mark>");
const gNote=g=>{const n=S.lang=="vi"?g.nv:g.ne;if(!n)return"";const pts=n.split(/\s*•\s*/).filter(Boolean);return`<div class="gn"><div class="mu">💡 ${t("use")}</div>${pts.length>1?`<ul>${pts.map(p=>`<li>${p}</li>`).join("")}</ul>`:`<p>${n}</p>`}</div>`};
const gStat=g=>{const s=S.gs&&S.gs[g.p];return s?`<span class="gs ${s[0]/s[1]>=.7?"ok":""}">✓${s[0]}/${s[1]}</span>`:""};
function glist(){const q=gSearch.trim().toLowerCase();GA=D.grammar.filter(inF).filter(g=>!q||[g.p,g.vi,g.en,g.form,g.nv||""].join(" ").toLowerCase().includes(q)||gp(g.p).includes(q));
if(!GA.length)return`<p class="c mu">${t("none")}</p>`;
return GA.map((g,i)=>{const o=gOpen===i;return`<div class="gc ${o?"open":""}"><button class="gh" onclick="gOpen=${o?-1:i};gRe()"><span class="badge">N${g.l}</span><span class="gt">${g.p} ${gStat(g)}</span><span class="gm">${g[S.lang]}</span><span class="gx">${o?"▲":"▼"}</span></button>${o?`<div class="gb"><div class="form"><div class="mu">${t("form")}</div><b>${g.form}</b></div>${gNote(g)}<div class="mu" style="margin:10px 0 2px">${t("exs")}</div>${g.ex.map((e,k)=>`<div class="gex"><button class="pill" onclick="speak(gp(GA[${i}].ex[${k}].j))">▶</button><div><div class="jp">${hl(e.j)}</div><div class="mu">🇬🇧 ${e.en}<br>🇻🇳 ${e.vi}</div></div></div>`).join("")}<button class="go" style="width:100%;margin-top:8px" onclick="S.qm='g';GQ=null;GQp='${g.p}';save();go('quiz')">✏️ ${t("gTry")}</button></div>`:""}</div>`}).join("")}
const gRe=()=>{const e=$("#gl");if(e)e.innerHTML=glist();else render()};
function Gram(){return chips()+`<div class="row">${furiRow()}</div><input id="gsq" type="search" placeholder="🔍 ${t("gFind")}" value="${esc(gSearch)}" oninput="gSearch=this.value;gOpen=-1;gRe()" style="width:100%;margin:4px 0 6px"><div id="gl">${glist()}</div>`}
/* ---------- Grammar quiz: fill the highlighted part of an example sentence ---------- */
let GQ=null,GQp="",gsc=[0,0],gseen=new Set();
const gsegs=j=>(j.match(/\{[^}]*\}/g)||[]).map(s=>gp(s.slice(1,-1))).join(" … ");
function newGQ(){const pool=D.grammar.filter(inF);GQ=null;if(pool.length<4)return;let g=GQp&&pool.find(x=>x.p==GQp);GQp="";
if(!g){const w=pool.map(x=>{const s=S.gs&&S.gs[x.p];return s?Math.max(.3,1.5-s[0]/s[1]):1.6});let r=Math.random()*w.reduce((a,b)=>a+b,0),i=0;while((r-=w[i])>0&&i<pool.length-1)i++;g=pool[i]}
let ue=g.ex.map((_,k)=>k).filter(k=>!gseen.has(g.p+"|"+k));if(!ue.length){g.ex.forEach((_,k)=>gseen.delete(g.p+"|"+k));ue=g.ex.map((_,k)=>k)}const ek=ue[Math.random()*ue.length|0];gseen.add(g.p+"|"+ek);const e=g.ex[ek],ans=gsegs(e.j),seen=new Set([ans]),near=D.grammar.filter(x=>x.p!=g.p&&Math.abs(x.l-g.l)<=1),o=[ans];
for(const x of shuf(near.flatMap(x=>x.ex.map(y=>gsegs(y.j))))){if(o.length>=4)break;if(!x||seen.has(x)||x.length>ans.length+8)continue;seen.add(x);o.push(x)}
if(o.length<4)return;GQ={g,e,ans,o:shuf(o),a:-1}}
function gans(i){if(GQ.a>=0)return;GQ.a=i;dinc("g");gsc[1]++;const ok=GQ.o[i]==GQ.ans;S.gs=S.gs||{};const s=S.gs[GQ.g.p]||[0,0];S.gs[GQ.g.p]=[s[0]+(ok?1:0),s[1]+1];if(ok){gsc[0]++;tick(6)}else tick(1);speak(gp(GQ.e.j));render()}
function GQuiz(){if(!GQ)newGQ();if(!GQ)return chips()+`<p class="c mu">${t("none")}</p>`;const{g,e,o,a,ans}=GQ;
return chips()+`<div class="card"><div class="mu">${t("gQ")} · ${t("score")} ${gsc[0]}/${gsc[1]}</div><p class="jp" style="text-align:center">${a>=0?hl(e.j):ruby(e.j.replace(/\{[^}]*\}/g,"＿＿"))}</p>${a>=0?`<p class="mu c">🇬🇧 ${e.en}<br>🇻🇳 ${e.vi}</p>`:""}${o.map((v,i)=>`<button class="opt ${a>=0?(v==ans?"ok":i==a?"bad":""):""}" onclick="gans(${i})">${v}</button>`).join("")}
${a>=0?`<div class="gb" style="margin-top:10px"><b>${g.p}</b> <span class="badge">N${g.l}</span> · ${g[S.lang]}<div class="mu">${g.form}</div>${gNote(g)}</div><div class="two" style="margin-top:8px"><button onclick="gSearch='${g.p}';gOpen=0;go('gram')">📖 ${t("gOpenP")}</button><button class="go" onclick="newGQ();render()">${t("next")} →</button></div>`:""}</div>`}
/* Kanji card back: words that use this kanji (easier levels first) */
const kvs=c=>{const a=D.vocab.filter(v=>v.j.includes(c.j)&&v.j!=c.j).sort((x,y)=>(Math.abs(x.l-c.l)-Math.abs(y.l-c.l))||y.l-x.l||x.j.length-y.j.length).slice(0,6);
return a.length?`<div class="ex" onclick="event.stopPropagation()"><div class="mu">${t("kWords")}</div>${a.map(v=>`<div class="kw" onclick="speak('${v.r}')"><b>${v.j}</b> <span class="mu">${v.r}</span> · ${v[S.lang]} <span class="badge">N${v.l}</span></div>`).join("")}</div>`:""};
/* ---------- Settings: lessons, sync, backup ---------- */
/* ---------- Sync UI: set up Supabase once on device 1, then open a link / scan a QR on device 2 ----------
   The link carries URL + key + code in the #hash (never sent to the web server). */
const SQL=`create table progress(id text primary key, data jsonb not null, updated_at timestamptz default now());
alter table progress enable row level security;
create policy "anon all" on progress for all to anon using (true) with check (true);`;
const b64e=s=>btoa(unescape(encodeURIComponent(s))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,""),b64d=s=>decodeURIComponent(escape(atob(s.replace(/-/g,"+").replace(/_/g,"/"))));
const syncLink=()=>location.href.split("#")[0]+"#sync="+b64e(JSON.stringify([S.sb.url,S.sb.key,S.sb.code]));
function linkIn(){const m=location.hash.match(/^#sync=(.+)$/);if(!m)return;history.replaceState(null,"",location.href.split("#")[0]);
try{const[u,k,c]=JSON.parse(b64d(m[1]));if(!u||!k||!c)throw 0;if(S.sb.code==c||confirm(t("lnkQ"))){S.sb={url:u,key:k,code:c};save();sync();tab="set"}}catch(e){alert(t("lnkBad"))}}
addEventListener("hashchange",()=>{linkIn();render()});let showLink=false;
function lnkShow(){showLink=!showLink;render();if(!showLink)return;const box=$("#qr");if(!box)return;const draw=()=>{try{box.innerHTML="";new QRCode(box,{text:syncLink(),width:220,height:220,correctLevel:QRCode.CorrectLevel.L})}catch(e){box.textContent=""}};
if(window.QRCode)return draw();const s=document.createElement("script");s.src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js";s.onload=draw;document.head.appendChild(s)}
async function lnkCopy(){const u=syncLink();try{if(navigator.share){await navigator.share({title:"日本語",url:u});return}await navigator.clipboard.writeText(u);alert(t("lnkCp"))}catch(e){prompt(t("lnkCp"),u)}}
function sbConnect(){const u=$("#su").value.trim(),k=$("#sk").value.trim();let c=$("#sc").value.trim();if(!u||!k)return alert(t("sbNeed"));if(!c){genC();c=$("#sc").value}S.sb={url:u,key:k,code:c};save();sync()}
function sbOff(){if(!confirm(t("sbOffQ")))return;S.sb={};showLink=false;save();render()}
function SyncCard(){const b=S.sb,on=b.url&&b.key&&b.code;
const form=`<input id="su" placeholder="https://xxxx.supabase.co" value="${esc(b.url||"")}"><input id="sk" placeholder="anon / publishable key" value="${esc(b.key||"")}" style="margin-top:6px"><div class="row"><input id="sc" placeholder="${t("sbCode")}" value="${esc(b.code||"")}" style="flex:1"><button onclick="genC()">${t("gen")}</button></div><button class="go" style="width:100%" onclick="sbConnect()">${t("sNow")}</button>`;
if(on)return`<div class="card"><b>☁️ ${t("sync")}</b><p>✅ ${t("sbOn")} · ${sy||"⏳"}</p><p class="mu">${t("sbAuto")}</p>
<div class="two"><button class="go" onclick="sync()">🔄 ${t("sbNow")}</button><button onclick="lnkShow()">📲 ${t("lnk")}</button></div>
${showLink?`<div class="c" style="margin-top:10px"><p class="mu">${t("lnkH")}</p><div id="qr" class="qr"></div><button class="pill" onclick="lnkCopy()">🔗 ${t("lnkB")}</button><p class="mu" style="font-size:12px">⚠️ ${t("lnkW")}</p></div>`:""}
<details style="margin-top:10px"><summary class="mu">${t("sbEdit")}</summary>${form}<button class="no" style="width:100%;margin-top:6px" onclick="sbOff()">✖ ${t("sbOff")}</button></details></div>`;
return`<div class="card"><b>☁️ ${t("sync")}</b><p class="mu">${t("sbWhy")}</p>
<p><b>${t("sbS2")}</b> ${t("sbS2h")}</p>
<details><summary><b>${t("sbS1")}</b> ${t("sbS1h")}</summary><ol class="pl"><li>${t("sbI1")}</li><li>${t("sbI2")}<pre class="sql">${SQL}</pre><button class="pill" onclick="navigator.clipboard.writeText(SQL).then(()=>alert('OK'))">📋 ${t("sbCopy")}</button></li><li>${t("sbI3")}</li></ol>${form}<p class="mu">${sy}</p></details>
<p class="mu" style="margin-top:8px">💡 ${t("sbAlt")}</p></div>`}
