function Settings(){const b=S.sb;return`<div class="card"><b>${t("nl")}</b> <select style="width:auto" onchange="S.nl=+this.value;save()">${[...new Set([5,10,15,20,30,S.nl])].sort((a,b)=>a-b).map(n=>`<option ${S.nl==n?"selected":""}>${n}</option>`).join("")}</select>${plan()?`<p class="mu" style="margin:6px 0 0">🎯 ${t("pAuto")}</p>`:""}</div>
<div class="card"><b>${t("lt")}</b><p class="mu">${t("ltH")}</p><textarea id="lt" rows="4"></textarea><div class="row"><input id="ln" type="number" min="0" max="50" placeholder="${t("lesson")}" style="width:100px"><button class="go" onclick="tagL()">${t("tag")}</button></div><p id="lr" class="mu"></p></div>
${SyncCard()}
<div class="card"><b>💽 ${t("stor")}</b><p class="mu">${t("stL")}.<br>${t("stP")}: ${persisted?"✅ "+t("stPy"):"⚠️ "+t("stPn")}.<br>${t("stC")}: ${Object.keys(S.b).length} · ${t("stS")}: ${(JSON.stringify(S).length/1024).toFixed(0)} KB<br>${t("bkD")}: ${S.lb?new Date(S.lb).toLocaleString():t("never")} · ${t("stY")}: ${S.ls0?new Date(S.ls0).toLocaleString():t("never")}</p><div class="row"><button class="pill" onclick="bk()">💾 ${t("bk")}</button><label class="pill" style="border:1px solid var(--bd);background:var(--cd)">📥 ${t("rs")}<input type="file" accept=".json" hidden onchange="rst(this.files[0])"></label></div></div>`}
function tagL(){const n=+$("#ln").value||0,tk=$("#lt").value.split(/[\s,、，]+/).filter(Boolean),all=[...D.vocab,...D.kanji,...D.grammar],miss=[];let c=0;tk.forEach(w=>{const f=all.filter(x=>x.j==w||x.r==w||x.p==w||x.p=="〜"+w);if(!f.length)return miss.push(w);f.forEach(x=>{S.ls[x.id]=[n,Date.now()];c++})});save();$("#lr").textContent=`${t("tagged")}: ${c}. ${miss.length?t("miss")+": "+miss.join(" "):""}`}
function genC(){const a="abcdefghjkmnpqrstuvwxyz23456789";$("#sc").value=[...crypto.getRandomValues(new Uint8Array(24))].map(v=>a[v%a.length]).join("")}
function saveSb(){S.sb={url:$("#su").value.trim(),key:$("#sk").value.trim(),code:$("#sc").value.trim()};save();sync()}
